mapper.select:
SELECT * FROM msg_queue
WHERE STAT = '0' AND REQUEST_TIME <= #{requestTime}
ORDER BY REQUEST_TIME ASC

mapper.insert:
INSERT INTO msg_queue (
    MSG_TYPE, DSTADDR, CALLBACK, STAT, SUBJECT, TEXT,
    INSERT_TIME, REQUEST_TIME, SENDER_CODE,
    EXT_COL0, EXT_COL1, EXT_COL2, EXT_COL3
) VALUES (
    #{msgType}, #{dstaddr}, #{callback}, '0', #{subject}, #{text}, NOW(),

        #{requestTime}
        NOW()
    ,
    '301200115',
    #{extCol0}, #{extCol1}, #{extCol2}, #{extCol3}
)

INSERT INTO msg_queue (
    MSG_TYPE, DSTADDR, CALLBACK, STAT, SUBJECT, TEXT,
    INSERT_TIME, REQUEST_TIME, FILECNT, FILELOC1, FILELOC2, FILELOC3,
    SENDER_CODE, EXT_COL0, EXT_COL1, EXT_COL2, EXT_COL3
) VALUES (
    #{msgType}, #{dstaddr}, #{callback}, '0',

        ''
        #{subject}
    ,
    #{text}, NOW(),

        #{requestTime}
        NOW()
    ,
    IFNULL(#{filecnt}, 0), #{fileloc1}, #{fileloc2}, #{fileloc3},
    '301200115', #{extCol0}, #{extCol1}, #{extCol2}, #{extCol3}
)

